import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Tasks real-time board sync (1.8.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tasks real-time board sync (1.8.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/tasks-realtime-board-sync-1-8-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tasks real-time board sync (1.8.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/tasks-realtime-board-sync-1-8-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/tasks-realtime-board-sync-1-8-0-production-readiness.md","filePath":"deployment/tasks-realtime-board-sync-1-8-0-production-readiness.md","lastUpdated":1791131528000}'),s={name:"deployment/tasks-realtime-board-sync-1-8-0-production-readiness.md"};function n(r,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="tasks-real-time-board-sync-1-8-0-—-production-readiness-audit" tabindex="-1">Tasks real-time board sync (1.8.0) — Production Readiness Audit <a class="header-anchor" href="#tasks-real-time-board-sync-1-8-0-—-production-readiness-audit" aria-label="Permalink to &quot;Tasks real-time board sync (1.8.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-04</td></tr><tr><td><strong>Re-audited</strong></td><td>2026-10-04 (payload/unassign/complete remediations closed)</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong></td></tr><tr><td><strong>Scope</strong></td><td>Private board channel <code>tenant.{id}.tasks.board</code> + <code>TaskCreated</code>/<code>TaskUpdated</code>/<code>TaskStatusChanged</code>/<code>TaskAssigned</code>/<code>TaskDeleted</code> broadcasts; SPA debounce-invalidate hook; catalog <strong>tasks 1.7.0 → 1.8.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/developer-guide/tasks">Tasks developer guide</a> · <a href="/user-guide/tasks-overview">Tasks overview</a> · <a href="/deployment/leads-realtime-board-sync-1-8-0-production-readiness">Leads 1.8.0 readiness</a> · <a href="/deployment/opportunities-realtime-board-sync-1-3-0-production-readiness">Opportunities 1.3.0 readiness</a> (pattern sources) · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>The Tasks Kanban board now stays in sync across open tabs/users without a manual refresh. Backend fires five <code>ShouldBroadcastNow</code> events off the existing <code>TaskEventSubscriber</code> domain-event handlers onto a new private Reverb channel; the SPA joins that channel only while the board view is mounted and debounces invalidation of the board + stats queries so a burst of changes collapses into one refetch. The design deliberately mirrors the <strong>Leads 1.8.0 / Opportunities 1.3.0 / Live Chat inbox invalidate pattern</strong> (refetch-on-signal) and explicitly avoids the <strong>Team Chat message-patching pattern</strong> (no per-card payload merging). Board columns are <code>TaskStatusEnum</code> values (<code>status</code> / <code>previous_status</code>), not pipeline stages.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no parallel realtime architecture; reuses <code>window.Echo</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Channel auth: same tenant + <code>tasks.view</code> (mirrors <code>LeadBoardChannel</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Cross-tenant isolation</td><td><strong>Pass</strong> — different <code>tenantId</code> on the channel name is rejected by <code>TaskBoardChannel::join</code></td></tr><tr><td>Broadcasts fire on create / update / status change / assign / unassign / complete / delete</td><td><strong>Pass</strong></td></tr><tr><td>SPA payload contract (<code>broadcastWith</code>)</td><td><strong>Pass</strong> — <code>action</code>, <code>task_id</code>, <code>status</code>, <code>previous_status</code>, <code>assigned_to</code></td></tr><tr><td>Title-only update does not emit <code>TaskStatusChanged</code></td><td><strong>Pass</strong></td></tr><tr><td><code>assigned_to</code> present on assigned payload (including unassign → <code>null</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Broadcast failures never break task writes (<code>SafeRealtimeBroadcast</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Domain events stay separate from broadcast classes</td><td><strong>Pass</strong> — new <code>App\\Events\\Task\\*Broadcast</code> namespace; existing <code>App\\Events\\Task{Created,Updated,...}</code> untouched</td></tr><tr><td>Catalog migrate-only <strong>1.8.0</strong> + CatalogSeeder companion</td><td><strong>Pass</strong></td></tr><tr><td>SPA debounced invalidate (~200ms), board-view-only subscription</td><td><strong>Pass</strong></td></tr><tr><td>Pest coverage</td><td><strong>Pass</strong> — <code>TaskRealtimeBoardTest</code> (8) + <code>TasksModuleVersion180BumpTest</code> (2) = <strong>10 passed / 27 assertions</strong></td></tr><tr><td>Frontend <code>tsc -b</code></td><td><strong>Pass</strong></td></tr><tr><td>Security: cross-tenant isolation</td><td><strong>Pass</strong></td></tr><tr><td>Security: assignee-scoped board metadata (tenant-wide channel)</td><td><strong>Accepted</strong> — identical to Leads 1.8.0; payload is id-only and SPA ignores content (API refetch remains assignee-scoped)</td></tr></tbody></table><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="closed-audit-remediations" tabindex="-1">Closed (audit remediations) <a class="header-anchor" href="#closed-audit-remediations" aria-label="Permalink to &quot;Closed (audit remediations)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>A1</td><td>Medium</td><td>Tests asserted event properties only — SPA contract (<code>broadcastWith</code> / channel name) was unverified</td><td><code>TaskRealtimeBoardTest</code> now asserts <code>private-tenant.{id}.tasks.board</code>, <code>action</code>, <code>task_id</code>, <code>status</code>, <code>previous_status</code></td></tr><tr><td>A2</td><td>Medium</td><td>Unassign (<code>assigned_to: null</code>) claimed Pass with no coverage</td><td>Assign test now posts <code>assigned_to: null</code> and asserts payload <code>assigned_to</code> is <code>null</code></td></tr><tr><td>A3</td><td>Low</td><td><code>POST …/complete</code> (list/board complete) not asserted for status broadcast</td><td>New case: complete → <code>TaskStatusChangedBroadcast</code> with <code>previous_status=open</code> and payload <code>status=completed</code></td></tr><tr><td>A4</td><td>Low</td><td>Title-only update could emit a spurious status_changed if enum/string compare drifted</td><td>Title rename fakes both events and <code>assertNotDispatched(TaskStatusChangedBroadcast)</code></td></tr><tr><td>A5</td><td>Low</td><td><code>statusValue()</code> only handled <code>TaskStatusEnum</code> + string</td><td>Also unwraps <code>BackedEnum</code> string values</td></tr></tbody></table><h3 id="accepted-intentional-ops-—-not-defects" tabindex="-1">Accepted (intentional / ops — not defects) <a class="header-anchor" href="#accepted-intentional-ops-—-not-defects" aria-label="Permalink to &quot;Accepted (intentional / ops — not defects)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Notes</th></tr></thead><tbody><tr><td>R1</td><td>Info</td><td>Restore / force-delete do not emit board broadcasts — same as Leads 1.8.0 / Opportunities 1.3.0</td></tr><tr><td>R2</td><td>Info</td><td>Notes, tags, and restore stay off the board channel (invalidate-on-signal for write paths only)</td></tr><tr><td>R3</td><td>Ops</td><td>No Reverb in CI; live two-session smoke remains a staging checklist item</td></tr><tr><td>R4</td><td>Info</td><td>No Playwright realtime spec — same as Leads / Live Chat</td></tr><tr><td>R5</td><td>Info</td><td>Mobile Tasks board realtime is out of scope (web Kanban only)</td></tr><tr><td>R6</td><td>Info</td><td>Channel join is tenant + <code>tasks.view</code> (not per-assignee). Payload is id-only; HTTP refetch stays assignee-scoped</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li><code>app/Broadcasting/TaskBoardChannel.php</code> — private channel auth, same shape as <code>LeadBoardChannel</code> (tenant match + <code>tasks.view</code>).</li><li><code>routes/channels.php</code> — registers <code>tenant.{tenantId}.tasks.board</code>.</li><li><code>app/Events/Task/TaskBoardBroadcastPayload.php</code> — shared payload builder (<code>action</code>, <code>task_id</code>, <code>uuid</code>, <code>actor_id</code>, <code>status</code>, optional <code>previous_status</code> / <code>assigned_to</code>).</li><li><code>app/Events/Task/Task{Created,Updated,StatusChanged,Assigned,Deleted}Broadcast.php</code> — <code>ShouldBroadcastNow</code>, each <code>broadcastAs()</code> matching the SPA&#39;s <code>.TaskXxx</code> listener name.</li><li><code>app/Listeners/TaskEventSubscriber.php</code> — create/update/assign/delete handlers fire the matching broadcast via <code>SafeRealtimeBroadcast::dispatch</code>; <code>TaskStatusChangedBroadcast</code> fires from <code>handleTaskUpdated</code> when status actually changed (no new domain event).</li><li>Catalog: <code>database/migrations/2026_10_04_193500_bump_tasks_module_to_1_8_0.php</code> (migrate-only, reversible) + <code>CatalogSeeder</code> <code>tasks</code> version <strong>1.8.0</strong>.</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><code>src/hooks/use-tasks-board-realtime.ts</code> — subscribes via shared <code>window.Echo</code>; listens for all five events; debounces (~200ms) invalidate of <code>QUERY_KEYS.taskBoard</code> + <code>QUERY_KEYS.taskStats</code>.</li><li><code>src/pages/tasks/tasks-page.tsx</code> — calls the hook with <code>enabled: viewMode === &#39;board&#39;</code>.</li><li><code>src/types/api.ts</code> — <code>TaskBoardRealtimePayload</code> type.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Tasks user/developer guides updated; product roadmap; this readiness doc; CHANGELOG entry.</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>herd php artisan test --compact tests/Feature/Tenant/Task/TaskRealtimeBoardTest.php tests/Feature/Central/Catalog/TasksModuleVersion180BumpTest.php</span></span>
<span class="line"><span>Tests: 10 passed (27 assertions)</span></span></code></pre></div><p><code>TaskRealtimeBoardTest</code> covers: channel auth (owner / <code>tasks.view</code> staff / no-permission / cross-tenant); create payload + private channel name; title update without status_changed; PUT status + <code>previous_status</code> payload; POST complete; assign + unassign <code>assigned_to</code>; delete; broadcast-failure write resilience. <code>TasksModuleVersion180BumpTest</code> covers <code>bumpVersion</code> + CatalogSeeder companion <strong>1.8.0</strong>.</p><p><code>vendor/bin/pint --dirty --format agent</code> — pass.</p><p>Frontend <code>npm run typecheck</code> (<code>tsc -b</code>) — pass.</p><h2 id="known-limitations-deferred" tabindex="-1">Known limitations / deferred <a class="header-anchor" href="#known-limitations-deferred" aria-label="Permalink to &quot;Known limitations / deferred&quot;">​</a></h2><ul><li>No Reverb broadcaster runs in CI; broadcast dispatch is verified via <code>Event::fake([...])</code> + <code>Event::assertDispatched(...)</code> rather than an end-to-end socket round-trip. A live Reverb smoke test on staging is recommended before/at go-live.</li><li>No dedicated Playwright realtime spec — same as Leads 1.8.0 / Live Chat.</li><li>Board cards still fully refetch on any board-relevant event (invalidate, not patch) — intentional.</li><li>Mobile Tasks board realtime is out of scope (web Kanban only).</li><li>Notes, tags, restore, and force-delete do not emit board broadcasts (same as Leads / Opportunities).</li><li><strong>Assignee-scoped channel metadata (accepted):</strong> Channel join is tenant + <code>tasks.view</code> (same as Leads <code>leads.view</code>). Staff without <code>tasks.assign</code> can receive tenant-wide board event metadata (<code>task_id</code>, <code>uuid</code>, <code>status</code>, <code>assigned_to</code>, <code>actor_id</code>) even though HTTP board/list remain assignee-scoped. Payload excludes titles/notes; the SPA only invalidates queries and refetches through the scoped API.</li></ul><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — catalog <code>tasks</code> → <strong>1.8.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li>Open the Tasks board in two browser sessions (same tenant, both with <code>tasks.view</code>). In session A, create a task, drag a card between status columns, complete it, assign it, unassign it, then delete it. Confirm session B&#39;s board + KPI strip update within ~1s without a manual refresh.</li><li>Confirm a user without <code>tasks.view</code> cannot subscribe to <code>tenant.{id}.tasks.board</code> (channel auth rejects).</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Roll back the catalog migration (<code>down()</code> → <strong>1.7.0</strong>) after rolling back application code. The new broadcast classes and channel are additive — no schema changes, so rollback is code-only plus the catalog version bump.</p>`,30)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
